'use strict';

function partitionEvidence(entries) {
  if (!Array.isArray(entries)) {
    throw new TypeError('entries must be an array');
  }

  const result = { clips: [], documents: [], notes: [] };
  const destinations = {
    clip: result.clips,
    document: result.documents,
    note: result.notes
  };

  for (const entry of entries) {
    if (
      entry === null ||
      typeof entry !== 'object' ||
      typeof entry.id !== 'string' ||
      typeof entry.kind !== 'string' ||
      typeof entry.content !== 'string'
    ) {
      throw new TypeError('each entry must contain string id, kind, and content fields');
    }
    if (!Object.prototype.hasOwnProperty.call(destinations, entry.kind)) {
      throw new RangeError('unsupported evidence kind');
    }
    destinations[entry.kind].push(entry);
  }

  return result;
}

module.exports = { partitionEvidence };

