'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['partitionEvidence']);
const { partitionEvidence } = api;

assert.deepStrictEqual(partitionEvidence([]), { clips: [], documents: [], notes: [] });

const shared = { nested: true };
const entries = [
  { id: 'c1', kind: 'clip', content: 'alpha', extra: 1, shared },
  { id: 'd1', kind: 'document', content: '', extra: 2 },
  { id: 'n1', kind: 'note', content: 'memo' },
  { id: 'c1', kind: 'clip', content: 'alpha', extra: 1, shared }
];
const arraySnapshot = entries.slice();
const recordSnapshots = entries.map(record => ({ ...record }));
const result = partitionEvidence(entries);

assert.deepStrictEqual(result, {
  clips: [entries[0], entries[3]],
  documents: [entries[1]],
  notes: [entries[2]]
});
assert.deepStrictEqual(entries, arraySnapshot);
entries.forEach((record, index) => assert.deepStrictEqual(record, recordSnapshots[index]));
assert.notStrictEqual(result.clips[0], entries[0]);
assert.notStrictEqual(result.clips[1], entries[3]);
assert.notStrictEqual(result.documents[0], entries[1]);
assert.notStrictEqual(result.notes[0], entries[2]);
assert.strictEqual(result.clips[0].shared, shared);
result.clips[0].content = 'changed';
result.clips[0].extra = 99;
assert.strictEqual(entries[0].content, 'alpha');
assert.strictEqual(entries[0].extra, 1);

for (const invalid of [undefined, null, {}, 'x', 3]) {
  assert.throws(() => partitionEvidence(invalid), TypeError);
}
for (const invalidRecord of [null, 1, 'record', undefined]) {
  assert.throws(() => partitionEvidence([invalidRecord]), TypeError);
}
for (const record of [
  { kind: 'clip', content: 'x' },
  { id: 1, kind: 'clip', content: 'x' },
  { id: 'x', content: 'x' },
  { id: 'x', kind: 2, content: 'x' },
  { id: 'x', kind: 'clip' },
  { id: 'x', kind: 'clip', content: 2 }
]) {
  assert.throws(() => partitionEvidence([record]), TypeError);
}
assert.throws(
  () => partitionEvidence([{ id: 'x', kind: 'video', content: 'x' }]),
  RangeError
);

